// Tiny DOM helpers shared by every view.

const SVGNS = "http://www.w3.org/2000/svg";

function apply(el, attrs, kids) {
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v === false || v == null) continue;
    if (k === "html") el.innerHTML = v;
    else if (k.startsWith("on") && typeof v === "function") el.addEventListener(k.slice(2).toLowerCase(), v);
    else el.setAttribute(k, v === true ? "" : v);
  }
  for (const kid of kids.flat(Infinity)) {
    if (kid === false || kid == null) continue;
    el.append(kid.nodeType ? kid : document.createTextNode(String(kid)));
  }
  return el;
}

/** Create an HTML element. */
export const h = (tag, attrs, ...kids) => apply(document.createElement(tag), attrs, kids);
/** Create an SVG element. */
export const s = (tag, attrs, ...kids) => apply(document.createElementNS(SVGNS, tag), attrs, kids);

export const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const ease = {
  out: (t) => 1 - Math.pow(1 - t, 3),
  inOut: (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
  back: (t) => 1 + 2.4 * Math.pow(t - 1, 3) + 1.4 * Math.pow(t - 1, 2),
  linear: (t) => t,
};

export const reducedMotion = () =>
  typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * A scope collects timers, listeners and animation frames so a step or a view
 * can be torn down in one call without leaking anything.
 */
export function scope() {
  const cleanups = [];
  let dead = false;
  const api = {
    get dead() {
      return dead;
    },
    add(fn) {
      if (dead) fn();
      else cleanups.push(fn);
      return fn;
    },
    on(target, type, fn, opts) {
      target.addEventListener(type, fn, opts);
      api.add(() => target.removeEventListener(type, fn, opts));
    },
    timeout(fn, ms) {
      const id = setTimeout(() => !dead && fn(), ms);
      api.add(() => clearTimeout(id));
      return id;
    },
    interval(fn, ms) {
      const id = setInterval(() => !dead && fn(), ms);
      api.add(() => clearInterval(id));
      return id;
    },
    /** Run fn(dt, now) every frame until the scope ends. */
    frame(fn) {
      let id;
      let last = performance.now();
      const tick = (now) => {
        if (dead) return;
        fn(Math.min(0.1, (now - last) / 1000), now);
        last = now;
        id = requestAnimationFrame(tick);
      };
      id = requestAnimationFrame(tick);
      api.add(() => cancelAnimationFrame(id));
    },
    /** Animate t from 0 to 1 over ms. Resolves when finished (or immediately if the scope ends). */
    tween(ms, fn, easing = ease.out) {
      return new Promise((resolve) => {
        if (dead) return resolve();
        const start = performance.now();
        let id;
        const tick = (now) => {
          if (dead) return resolve();
          const t = clamp((now - start) / ms, 0, 1);
          fn(easing(t), t);
          if (t < 1) id = requestAnimationFrame(tick);
          else resolve();
        };
        id = requestAnimationFrame(tick);
        api.add(() => cancelAnimationFrame(id));
      });
    },
    wait(ms) {
      return new Promise((resolve) => api.timeout(resolve, ms));
    },
    end() {
      if (dead) return;
      dead = true;
      while (cleanups.length) {
        try {
          cleanups.pop()();
        } catch (e) {
          /* keep tearing down */
        }
      }
    },
  };
  return api;
}

/**
 * Turn an SVG node into a real, keyboard-reachable button.
 */
export function hot(el, label, fn) {
  el.setAttribute("role", "button");
  el.setAttribute("tabindex", "0");
  el.setAttribute("aria-label", label);
  el.classList.add("hot");
  el.addEventListener("click", (e) => {
    e.stopPropagation();
    fn(e);
  });
  el.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (!e.repeat) fn(e);
    }
  });
  return el;
}

/** A pulsing ring target at (x, y) in SVG units. */
export function ring(x, y, r, label, fn, extra = {}) {
  const g = s(
    "g",
    { class: "ring " + (extra.class || ""), transform: `translate(${x} ${y})` },
    s("circle", { class: "ring-pulse", r }),
    s("circle", { class: "ring-core", r }),
    s("circle", { class: "ring-dot", r: Math.max(4, r * 0.18) }),
    s("circle", { class: "ring-hit", r: r + 14 })
  );
  return hot(g, label, fn);
}

/** Shake an element briefly to say "no". */
export function shake(el) {
  el.classList.remove("shake");
  // Restart the animation.
  void el.getBoundingClientRect();
  el.classList.add("shake");
}

/** Format seconds as m:ss. */
export function mmss(sec) {
  const t = Math.max(0, Math.floor(sec));
  return Math.floor(t / 60) + ":" + String(t % 60).padStart(2, "0");
}

/** Convert a pointer event to SVG user-space coordinates. */
export function svgPoint(svg, e) {
  const pt = svg.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  const m = svg.getScreenCTM();
  return m ? pt.matrixTransform(m.inverse()) : pt;
}

// In-memory session state. Nothing is stored: the page must work in a sandbox with no storage.
import { guessCountry } from "./numbers.js";

const listeners = new Set();

export const state = {
  /** When the visitor arrived. Drives the survival clock and the closing message. */
  arrived: performance.now(),
  /** Ids of finished drills. */
  done: new Set(),
  country: guessCountry(),
  guessed: true,
  sound: true,
  /** Results worth showing on the closing card. */
  results: {},
};

/** The number to dial, e.g. "112". */
export const num = () => state.country.n;

export function subscribe(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function emit() {
  for (const fn of [...listeners]) fn(state);
}

export function setCountry(country) {
  state.country = country;
  state.guessed = false;
  emit();
}

export function markDone(id) {
  state.done.add(id);
  emit();
}

export function secondsHere() {
  return (performance.now() - state.arrived) / 1000;
}

// All sound is synthesised with Web Audio: a metronome, a chest "thump", and small feedback tones.
import { state } from "./state.js";

let ctx = null;
let master = null;

/** Create (or resume) the audio context. Must be called from a user gesture. */
export function wake() {
  try {
    if (!ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ctx = new AC();
      master = ctx.createGain();
      master.gain.value = 0.9;
      master.connect(ctx.destination);
    }
    if (ctx.state === "suspended") ctx.resume();
  } catch (e) {
    ctx = null;
  }
  return ctx;
}

function tone({ freq = 440, to = null, dur = 0.12, type = "sine", gain = 0.2, at = 0 }) {
  if (!state.sound) return;
  const c = wake();
  if (!c) return;
  try {
    const t = Math.max(c.currentTime, at || c.currentTime);
    const osc = c.createOscillator();
    const g = c.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (to) osc.frequency.exponentialRampToValueAtTime(to, t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g).connect(master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  } catch (e) {
    /* audio is a bonus, never a requirement */
  }
}

export const sfx = {
  /** The dull thud of a chest compression. */
  thump() {
    tone({ freq: 120, to: 46, dur: 0.14, type: "sine", gain: 0.5 });
  },
  tap() {
    tone({ freq: 520, to: 380, dur: 0.06, type: "triangle", gain: 0.14 });
  },
  good() {
    tone({ freq: 660, dur: 0.11, type: "triangle", gain: 0.16 });
    const c = wake();
    if (c) tone({ freq: 990, dur: 0.2, type: "triangle", gain: 0.16, at: c.currentTime + 0.09 });
  },
  bad() {
    tone({ freq: 170, to: 120, dur: 0.2, type: "square", gain: 0.07 });
  },
  shock() {
    tone({ freq: 1400, to: 80, dur: 0.35, type: "sawtooth", gain: 0.16 });
  },
  hit() {
    tone({ freq: 210, to: 70, dur: 0.11, type: "triangle", gain: 0.4 });
  },
  win() {
    const c = wake();
    if (!c) return;
    [523, 659, 784, 1047].forEach((f, i) =>
      tone({ freq: f, dur: 0.22, type: "triangle", gain: 0.15, at: c.currentTime + i * 0.09 })
    );
  },
  click(at, accent) {
    tone({ freq: accent ? 1320 : 990, dur: 0.05, type: "square", gain: accent ? 0.16 : 0.1, at });
  },
};

/**
 * A drift-free metronome. Audio clicks are scheduled ahead on the audio clock;
 * `onBeat(n)` fires on (roughly) the same instant for visuals. If audio is not
 * available it falls back to a wall-clock timer so the visual beat still works.
 */
export function metronome({ bpm = 110, onBeat, audible = () => true, accentEvery = 0 }) {
  const period = 60 / bpm;
  let running = false;
  let timer = null;
  let beat = 0;
  let nextAudio = 0;
  let startWall = 0;

  function loop() {
    if (!running) return;
    const c = ctx && ctx.state === "running" ? ctx : null;
    if (c) {
      while (nextAudio < c.currentTime + 0.12) {
        const n = beat++;
        const delay = Math.max(0, (nextAudio - c.currentTime) * 1000);
        if (audible()) sfx.click(nextAudio, accentEvery && n % accentEvery === 0);
        setTimeout(() => running && onBeat && onBeat(n), delay);
        nextAudio += period;
      }
    } else {
      const now = performance.now() / 1000;
      while (startWall + beat * period <= now) {
        const n = beat++;
        if (onBeat) onBeat(n);
      }
    }
  }

  return {
    get running() {
      return running;
    },
    start() {
      if (running) return;
      running = true;
      beat = 0;
      const c = wake();
      nextAudio = c ? c.currentTime + 0.08 : 0;
      startWall = performance.now() / 1000 + 0.08;
      timer = setInterval(loop, 25);
      loop();
    },
    stop() {
      running = false;
      clearInterval(timer);
    },
  };
}

// Pictogram people, drawn from a handful of named joints so they can be posed and animated.
import { s, lerp, ease } from "./ui.js";

/**
 * A figure is a list of parts drawn over named points.
 *   { pts: ["shL","elL","haL"], w: 13, halo: true }   a limb (thick round stroke)
 *   { pts: [...], w: 14, closed: true }               a filled body shape
 *   { head: "head", r: 17 }                           the head
 */
export class Figure {
  constructor(spec, pose, cls = "") {
    this.spec = spec;
    this.pose = {};
    this.el = s("g", { class: "fig " + cls });
    this.nodes = spec.map((part) => {
      if (part.head) {
        const c = s("circle", { class: "fig-head", r: part.r });
        this.el.append(c);
        return { part, c };
      }
      const halo = part.halo
        ? s("path", { class: "fig-halo", "stroke-width": part.w + (part.haloW || 7), fill: "none" })
        : null;
      const p = s("path", {
        class: part.closed ? "fig-body" : "fig-limb",
        "stroke-width": part.w,
      });
      if (halo) this.el.append(halo);
      this.el.append(p);
      return { part, p, halo };
    });
    this.set(pose);
  }

  set(pose) {
    Object.assign(this.pose, pose);
    const P = this.pose;
    for (const { part, c, p, halo } of this.nodes) {
      if (part.head) {
        const at = P[part.head];
        c.setAttribute("cx", at[0].toFixed(2));
        c.setAttribute("cy", at[1].toFixed(2));
        continue;
      }
      const d =
        part.pts.map((name, i) => (i ? "L" : "M") + P[name][0].toFixed(2) + " " + P[name][1].toFixed(2)).join("") +
        (part.closed ? "Z" : "");
      p.setAttribute("d", d);
      if (halo) halo.setAttribute("d", d);
    }
    return this;
  }

  /** Animate to a pose inside a scope. */
  to(pose, ms, sc, easing = ease.inOut) {
    const from = {};
    for (const k of Object.keys(pose)) from[k] = this.pose[k] ? [...this.pose[k]] : [...pose[k]];
    return sc.tween(
      ms,
      (t) => {
        const cur = {};
        for (const k of Object.keys(pose)) cur[k] = [lerp(from[k][0], pose[k][0], t), lerp(from[k][1], pose[k][1], t)];
        this.set(cur);
      },
      easing
    );
  }
}

// ── Front view (also reads as a person lying on their back, seen from above) ──────────────

export const FRONT_SPEC = [
  { pts: ["hipL", "knL", "ftL"], w: 14 },
  { pts: ["hipR", "knR", "ftR"], w: 14 },
  { pts: ["shL", "shR", "hipR", "hipL"], w: 14, closed: true },
  { head: "head", r: 17 },
  { pts: ["shL", "elL", "haL"], w: 12.5, halo: true },
  { pts: ["shR", "elR", "haR"], w: 12.5, halo: true },
];

export const FRONT = {
  head: [0, -30],
  shL: [-22, 4],
  shR: [22, 4],
  hipL: [-13, 78],
  hipR: [13, 78],
  elL: [-32, 40],
  haL: [-34, 76],
  elR: [32, 40],
  haR: [34, 76],
  knL: [-15, 126],
  ftL: [-16, 174],
  knR: [15, 126],
  ftR: [16, 174],
};

export const pose = (overrides) => ({ ...FRONT, ...overrides });

// ── Side view ───────────────────────────────────────────────────────────────────────────

export const SIDE_SPEC = [
  { pts: ["hip", "knB", "ftB"], w: 24 },
  { pts: ["sh", "elB", "haB"], w: 20 },
  { pts: ["neck", "hip"], w: 44 },
  { pts: ["hip", "knA", "ftA"], w: 24, halo: true, haloW: 6 },
  { head: "head", r: 29 },
  { pts: ["sh", "elA", "haA"], w: 20, halo: true, haloW: 8 },
];

// The drill engine: a stage you act on, a coach panel that tells you why, and a takeaway to keep.
import { h, s, scope } from "./ui.js";
import { sfx, wake } from "./audio.js";
import { num } from "./state.js";

/** Replace {n} with the visitor's emergency number. */
export const fill = (text) => String(text).replaceAll("{n}", num());

/**
 * def = {
 *   id, num, name, blurb, minutes,
 *   steps: [{ tag, title, text, setup(ctx) }],
 *   keep: [{ word, line }],
 * }
 * ctx = { stage, svg(label), sc, say(text, kind), done(text), actions, hint(text) }
 */
export function runDrill(def, { onExit, onFinish, nextLabel }) {
  let index = 0;
  let stepScope = null;

  const pips = h("ol", { class: "drill-pips", "aria-label": "Steps" });
  const head = h(
    "header",
    { class: "drill-head" },
    h(
      "div",
      { class: "drill-id" },
      h("span", { class: "drill-num" }, def.num),
      h("span", { class: "drill-name" }, def.name)
    ),
    pips,
    h("button", { class: "btn btn-ghost btn-small", type: "button", onclick: () => exit() }, "All drills")
  );

  const stage = h("div", { class: "stage" });
  const kicker = h("p", { class: "step-kicker" });
  const title = h("h2", { class: "step-title", tabindex: "-1" });
  const text = h("p", { class: "step-text" });
  const actions = h("div", { class: "step-actions" });
  const say = h("div", { class: "step-say", role: "status", "aria-live": "polite" });
  const nextBtn = h("button", { class: "btn btn-primary btn-next", type: "button", onclick: () => next() }, "Next");
  const skipBtn = h("button", { class: "btn-link", type: "button", onclick: () => next() }, "Skip this step");
  const foot = h("div", { class: "step-foot" }, nextBtn, skipBtn);
  const panel = h("div", { class: "panel" }, kicker, title, text, actions, say, foot);
  const body = h("div", { class: "drill-body" }, stage, panel);
  const root = h("section", { class: "drill", "data-drill": def.id }, head, body);

  function exit() {
    stepScope?.end();
    onExit();
  }

  function renderPips() {
    pips.replaceChildren(
      ...def.steps.map((st, i) =>
        h(
          "li",
          { class: "pip" + (i < index ? " is-done" : i === index ? " is-now" : ""), "aria-current": i === index ? "step" : null },
          h("span", { class: "pip-n" }, String(i + 1)),
          h("span", { class: "pip-t" }, st.tag)
        )
      )
    );
  }

  function show(i) {
    stepScope?.end();
    stepScope = scope();
    index = i;
    const st = def.steps[i];
    renderPips();
    root.classList.remove("is-keep");
    stage.className = "stage" + (st.stageClass ? " " + st.stageClass : "");
    stage.replaceChildren();
    actions.replaceChildren();
    say.replaceChildren();
    say.className = "step-say";
    kicker.textContent = `Step ${i + 1} of ${def.steps.length} · ${st.tag}`;
    title.textContent = fill(st.title);
    text.innerHTML = fill(st.text);
    nextBtn.disabled = true;
    nextBtn.textContent = i === def.steps.length - 1 ? "What to remember" : "Next step";
    nextBtn.classList.remove("is-ready");
    skipBtn.hidden = false;

    const ctx = {
      stage,
      actions,
      sc: stepScope,
      /** Make the standard 600×500 stage drawing. */
      svg(label, viewBox = "0 0 600 500") {
        const el = s("svg", { class: "stage-svg", viewBox, role: "group", "aria-label": label });
        stage.append(el);
        return el;
      },
      /** Coach feedback. kind: "ok" | "no" | "info" */
      say(message, kind = "info") {
        say.className = "step-say is-" + kind;
        say.replaceChildren(
          h("span", { class: "say-mark", "aria-hidden": "true" }, kind === "ok" ? "✓" : kind === "no" ? "✕" : "→"),
          h("span", { html: fill(message) })
        );
        if (kind === "no") sfx.bad();
      },
      /** Step finished: unlock Next and explain why it matters. */
      done(message) {
        if (stepScope.dead) return;
        if (message) ctx.say(message, "ok");
        sfx.good();
        nextBtn.disabled = false;
        nextBtn.classList.add("is-ready");
        skipBtn.hidden = true;
        stage.classList.add("is-done");
      },
      /** Rewrite the instruction as the step moves on. */
      prompt(newTitle, newText) {
        if (newTitle != null) title.textContent = fill(newTitle);
        if (newText != null) text.innerHTML = fill(newText);
      },
    };
    st.setup(ctx);
    if (i > 0) title.focus({ preventScroll: true });
    root.scrollIntoView({ block: "start" });
  }

  function next() {
    wake();
    if (index < def.steps.length - 1) show(index + 1);
    else keep();
  }

  function keep() {
    stepScope?.end();
    stepScope = scope();
    index = def.steps.length;
    renderPips();
    root.classList.add("is-keep");
    sfx.win();
    onFinish();
    const card = h(
      "div",
      { class: "keep" },
      h("p", { class: "keep-kicker" }, `${def.num} · ${def.name} · done`),
      h("h2", { class: "keep-title", tabindex: "-1" }, def.keepTitle || "Keep this."),
      h(
        "ol",
        { class: "keep-list" },
        def.keep.map((k, i) =>
          h(
            "li",
            { style: `--i:${i}` },
            h("span", { class: "keep-word" }, k.word),
            h("span", { class: "keep-line", html: fill(k.line) })
          )
        )
      ),
      def.also ? h("div", { class: "keep-also" }, def.also.map((a) => h("p", { html: fill(a) }))) : null,
      h(
        "div",
        { class: "keep-actions" },
        h("button", { class: "btn btn-primary", type: "button", onclick: () => onExit("next") }, nextLabel()),
        h("button", { class: "btn btn-ghost", type: "button", onclick: () => show(0) }, "Do it again"),
        h("button", { class: "btn-link", type: "button", onclick: () => onExit() }, "All drills")
      )
    );
    body.replaceChildren(card);
    card.querySelector(".keep-title").focus({ preventScroll: true });
    root.scrollIntoView({ block: "start" });
    // Restore the two-pane body if they choose to repeat.
    stepScope.add(() => body.replaceChildren(stage, panel));
  }

  show(0);
  return { el: root, destroy: () => stepScope?.end() };
}

/**
 * A judgement call: a short scenario on the stage, and choices in the panel.
 * options: [{ label, ok, why }]
 */
export function choiceStep({ tag, title, text, scene, quote, options, after }) {
  return {
    tag,
    title,
    text,
    stageClass: "stage--scene",
    setup(ctx) {
      ctx.stage.append(
        h(
          "div",
          { class: "scene" },
          h("p", { class: "scene-label" }, scene || "What do you do?"),
          h("p", { class: "scene-quote", html: fill(quote) })
        )
      );
      let solved = false;
      const buttons = options.map((opt) => {
        const b = h(
          "button",
          {
            class: "btn btn-choice",
            type: "button",
            onclick: () => {
              if (solved) return;
              if (opt.ok) {
                solved = true;
                b.classList.add("is-right");
                buttons.forEach((x) => x !== b && (x.disabled = true));
                ctx.done(opt.why);
                if (after) after(ctx);
              } else {
                b.classList.add("is-wrong");
                b.disabled = true;
                ctx.say(opt.why, "no");
              }
            },
          },
          fill(opt.label)
        );
        return b;
      });
      ctx.actions.append(...buttons);
    },
  };
}

// Drill 01 — a person collapses. Check, call, push, shock.
import { h, s, ring, shake, clamp, ease } from "../ui.js";
import { Figure, FRONT_SPEC, FRONT, pose } from "../figure.js";
import { sfx, metronome, wake } from "../audio.js";
import { state, num } from "../state.js";

const RATE_MIN = 100;
const RATE_MAX = 120;
const GOAL = 30;

// ── Step 1: check ───────────────────────────────────────────────────────────────────────

function check(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("A person lying on the ground, seen from above");
  svg.append(s("ellipse", { class: "floor", cx: 300, cy: 276, rx: 278, ry: 128 }));
  const body = s("g", { transform: "translate(159 270) rotate(-90) scale(2.1)" });
  const fig = new Figure(FRONT_SPEC, FRONT);
  const wrap = s("g", {}, body);
  body.append(fig.el);
  svg.append(wrap);

  const shout = s("text", { class: "shout", x: 300, y: 96, "text-anchor": "middle" }, "“ARE YOU OKAY?”");
  shout.style.opacity = 0;
  svg.append(shout);

  const gasp = s(
    "g",
    { class: "gasp", opacity: 0 },
    s("path", { d: "M52 236 q-16 -10 -30 -4" }),
    s("path", { d: "M46 270 h-34" }),
    s("path", { d: "M52 304 q-16 10 -30 4" }),
    s("text", { x: 30, y: 352, "text-anchor": "middle" }, "…gasp…")
  );
  svg.append(gasp);

  let taps = 0;
  const rings = [];
  const onTap = () => {
    taps++;
    sfx.hit();
    shout.style.opacity = 1;
    shout.classList.remove("pop");
    void shout.getBBox();
    shout.classList.add("pop");
    sc.tween(260, (t) => wrap.setAttribute("transform", `translate(0 ${Math.sin(t * Math.PI * 3) * 5 * (1 - t)})`));
    if (taps === 1) ctx.say("Again. Firm taps, loud voice.", "info");
    if (taps >= 2) {
      rings.forEach((r) => r.remove());
      sc.timeout(listen, 700);
    }
  };
  rings.push(ring(167, 316, 26, "Tap the near shoulder", onTap), ring(167, 224, 26, "Tap the far shoulder", onTap));
  svg.append(...rings);

  function listen() {
    shout.style.opacity = 0.25;
    ctx.prompt(
      "No response. Is this breathing?",
      "Watch the chest for up to 10 seconds. You are looking for <b>normal</b> breathing — steady, quiet, regular."
    );
    ctx.say("Nothing. No movement, no answer.", "info");
    const torso = fig.nodes[2].p;
    const doGasp = () => {
      sc.tween(
        520,
        (t) => {
          const k = Math.sin(t * Math.PI);
          torso.setAttribute("stroke-width", 14 + 6 * k);
          gasp.setAttribute("opacity", k);
        },
        ease.linear
      );
    };
    sc.timeout(doGasp, 500);
    sc.interval(doGasp, 3400);

    const yes = h("button", { class: "btn btn-choice", type: "button" }, "Yes — they’re breathing");
    const no = h("button", { class: "btn btn-choice", type: "button" }, "No — that’s not normal breathing");
    yes.onclick = () => {
      yes.classList.add("is-wrong");
      yes.disabled = true;
      ctx.say(
        "Look again: one snoring gasp every few seconds, then nothing. That is <b>agonal gasping</b>. It is common in the first minutes after a heart stops, and it fools people into waiting.",
        "no"
      );
    };
    no.onclick = () => {
      no.classList.add("is-right");
      yes.disabled = true;
      ctx.done(
        "Right. <b>No response + no normal breathing = cardiac arrest.</b> Occasional gasps don’t count. If you’re not sure, act as if it is."
      );
    };
    ctx.actions.append(yes, no);
  }
}

// ── Step 2: call ────────────────────────────────────────────────────────────────────────

function call(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("Five bystanders standing around a collapsed person");
  svg.append(s("ellipse", { class: "floor", cx: 300, cy: 430, rx: 250, ry: 58 }));
  const victim = s("g", { transform: "translate(213 428) rotate(-90) scale(1.3)" });
  victim.append(new Figure(FRONT_SPEC, FRONT).el);
  svg.append(victim);

  const variants = [
    pose({ elL: [-36, 26], haL: [-12, -8] }), // hand to mouth
    pose({}),
    pose({ elL: [-30, 36], haL: [-4, 44], elR: [30, 36], haR: [4, 50] }), // arms crossed
    pose({ elR: [40, 12], haR: [20, -34], elL: [-40, 12], haL: [-20, -34] }), // hands on head
    pose({ elR: [34, 34], haR: [22, 62] }),
  ];
  const xs = [84, 192, 300, 408, 516];
  const ys = [112, 92, 104, 90, 110];
  let phase = 0;
  let caller = -1;

  const people = xs.map((x, i) => {
    const fig = new Figure(FRONT_SPEC, variants[i]);
    const dots = s("text", { class: "thought", x: 0, y: -62, "text-anchor": "middle" }, "…");
    const tag = s("text", { class: "tag", x: 0, y: 206, "text-anchor": "middle" }, "");
    const g = s(
      "g",
      { class: "bystander", transform: `translate(${x} ${ys[i]})` },
      s("rect", { class: "hit", x: -48, y: -74, width: 96, height: 290, rx: 12 }),
      fig.el,
      dots,
      tag
    );
    g.setAttribute("role", "button");
    g.setAttribute("tabindex", "0");
    g.setAttribute("aria-label", `Bystander ${i + 1}`);
    const act = () => pick(i);
    g.addEventListener("click", act);
    g.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        act();
      }
    });
    svg.append(g);
    return { g, fig, dots, tag, x, y: ys[i] };
  });

  ctx.say("Step one: choose a person to make the call.", "info");

  function pick(i) {
    const p = people[i];
    if (phase === 0) {
      phase = 1;
      caller = i;
      sfx.tap();
      p.g.classList.add("is-chosen");
      p.dots.textContent = "";
      p.tag.textContent = "CALLING " + num();
      p.fig.to({ elR: [38, 10], haR: [20, -26], elL: [-32, 40], haL: [-34, 76] }, 350, sc);
      ctx.prompt("Now send one for a defibrillator.", "Point at someone else: <b>“You — find an AED and bring it here.”</b> Shops, stations, gyms and offices often have one on the wall.");
      ctx.say("One person, one job. They’re dialling.", "ok");
    } else if (phase === 1) {
      if (i === caller) {
        shake(p.g);
        ctx.say("They’re on the phone. Pick someone else.", "no");
        return;
      }
      phase = 2;
      sfx.tap();
      p.g.classList.add("is-chosen");
      p.dots.textContent = "";
      p.tag.textContent = "FETCHING AED";
      const dir = p.x > 300 ? 1 : -1;
      const run = pose({
        elL: [-34, 28],
        haL: [-52, 44],
        elR: [38, 30],
        haR: [50, 6],
        knL: [-30, 118],
        ftL: [-56, 150],
        knR: [30, 120],
        ftR: [22, 170],
      });
      p.fig.to(run, 220, sc).then(() =>
        sc.tween(
          900,
          (t) => {
            p.g.setAttribute("transform", `translate(${p.x + dir * 420 * t} ${p.y - Math.abs(Math.sin(t * 14)) * 6})`);
            p.g.style.opacity = 1 - Math.max(0, t - 0.6) / 0.4;
          },
          ease.inOut
        )
      );
      people.forEach((q) => q.g.setAttribute("tabindex", "-1"));
      sc.timeout(
        () =>
          ctx.done(
            "“Somebody call an ambulance!” gets nobody — everyone waits for someone else. A finger pointed at one person gets it done. <b>Alone?</b> Call {n} on speaker yourself and start pushing."
          ),
        900
      );
    }
  }
}

// ── Step 3: push ────────────────────────────────────────────────────────────────────────

function torsoCloseUp(svg) {
  const g = s("g", { transform: "translate(300 150) scale(3)" });
  const fig = new Figure(FRONT_SPEC, pose({ elL: [-36, 40], haL: [-42, 76], elR: [36, 40], haR: [42, 76] }));
  g.append(fig.el);
  svg.append(g);
  return { g, fig };
}

function handsGlyph() {
  return s(
    "g",
    { class: "hands" },
    s("rect", { class: "hand hand-under", x: -34, y: -19, width: 68, height: 38, rx: 16, transform: "rotate(24)" }),
    s("rect", { class: "hand", x: -34, y: -19, width: 68, height: 38, rx: 16, transform: "rotate(-24)" }),
    s("path", { class: "hand-lines", d: "M-12 -8 l20 9 M-16 1 l20 9" })
  );
}

function push(ctx) {
  const { sc, stage } = ctx;

  const rateNum = h("b", {}, "—");
  const word = h("div", { class: "hud-word" }, "Place your hands");
  const count = h("b", {}, "0");
  const hud = h(
    "div",
    { class: "hud" },
    h("div", { class: "hud-rate" }, rateNum, h("span", {}, "pushes a minute")),
    word,
    h("div", { class: "hud-count" }, count, h("span", {}, `of ${GOAL} on tempo`))
  );
  stage.append(hud);

  const svg = ctx.svg("A chest seen from above");
  svg.append(s("ellipse", { class: "floor", cx: 300, cy: 300, rx: 250, ry: 215 }));
  const { g: torsoG } = torsoCloseUp(svg);

  // Tempo strip: every push lands as a dot; the band is 100–120 a minute.
  const strip = s("svg", { class: "tempo", viewBox: "0 0 600 84", role: "img", "aria-label": "Tempo of your last pushes" });
  const yFor = (bpm) => 78 - ((clamp(bpm, 70, 150) - 70) / 80) * 72;
  strip.append(
    s("rect", { class: "tempo-band", x: 46, y: yFor(RATE_MAX), width: 548, height: yFor(RATE_MIN) - yFor(RATE_MAX), rx: 4 }),
    s("text", { class: "tempo-label", x: 38, y: yFor(RATE_MAX) + 5, "text-anchor": "end" }, "120"),
    s("text", { class: "tempo-label", x: 38, y: yFor(RATE_MIN) + 5, "text-anchor": "end" }, "100"),
    s("text", { class: "tempo-edge", x: 590, y: 13, "text-anchor": "end" }, "too fast"),
    s("text", { class: "tempo-edge", x: 590, y: 80, "text-anchor": "end" }, "too slow")
  );
  const dotsG = s("g", {});
  strip.append(dotsG);
  stage.append(strip);

  // Phase A: where do the hands go?
  const spots = [
    { x: 300, y: 186, label: "High on the chest, near the throat", why: "Too high. That’s the top of the breastbone, near the throat." },
    { x: 362, y: 240, label: "Left side of the chest, over the heart", why: "Not over the heart on the left. The heart sits behind the breastbone — go for the <b>centre</b>." },
    { x: 300, y: 262, label: "Centre of the chest", ok: true },
    { x: 300, y: 352, label: "Stomach", why: "Too low — that’s the stomach. Pushing there does nothing for the heart." },
  ];
  const rings = spots.map((sp) =>
    ring(sp.x, sp.y, 22, sp.label, () => {
      if (sp.ok) {
        rings.forEach((r) => r.remove());
        begin();
      } else {
        shake(svg);
        ctx.say(sp.why, "no");
      }
    })
  );
  svg.append(...rings);
  ctx.say("First: where do your hands go? Tap the spot.", "info");

  // Phase B: compressions.
  const beatRing = s("circle", { class: "beat-ring", cx: 300, cy: 262, r: 46, opacity: 0 });
  const ripple = s("circle", { class: "ripple", cx: 300, cy: 262, r: 40, opacity: 0 });
  const hands = handsGlyph();
  const handsWrap = s("g", { transform: "translate(300 262)" }, hands);
  const cue = s("text", { class: "cue", x: 300, y: 478, "text-anchor": "middle" }, "TAP THE CHEST — OR PRESS SPACE");

  let active = false;
  let finished = false;
  let last = 0;
  let intervals = [];
  let all = [];
  let inZone = 0;
  let pushes = 0;
  let metro = null;
  let beatOn = true;
  let pressT = 0;

  function begin() {
    active = true;
    svg.append(beatRing, ripple, handsWrap, cue);
    svg.classList.add("is-pushable");
    word.textContent = "Push to the beat";
    ctx.prompt(
      "Push. Hard. Fast.",
      "Tap the chest in time with the beat — <b>100 to 120 pushes a minute</b>. Land " +
        GOAL +
        " on tempo. Halfway through, the beat goes silent and you keep it going alone."
    );
    ctx.say("Dead centre. Heel of one hand, the other on top, arms locked straight.", "ok");
    metro = metronome({
      bpm: 110,
      audible: () => beatOn,
      onBeat: () => {
        if (!beatOn) return;
        sc.tween(380, (t) => {
          beatRing.setAttribute("r", 46 + 34 * t);
          beatRing.setAttribute("opacity", 0.9 * (1 - t));
        });
      },
    });
    metro.start();
    sc.add(() => metro.stop());
  }

  function setWord(text, kind) {
    word.textContent = text;
    word.dataset.kind = kind || "";
  }

  function compress() {
    if (!active || finished) return;
    const now = performance.now();
    pushes++;
    sfx.thump();
    pressT = 1;
    cue.style.opacity = 0;
    const gap = now - last;
    last = now;
    if (pushes === 1 || gap > 1500) {
      intervals = [];
      if (pushes > 1) setWord("Keep going", "");
      return;
    }
    intervals.push(gap);
    if (intervals.length > 3) intervals.shift();
    const recent = intervals.slice(-2);
    const bpm = 60000 / (recent.reduce((a, b) => a + b, 0) / recent.length);
    all.push(60000 / gap);
    const ok = bpm >= RATE_MIN - 4 && bpm <= RATE_MAX + 4;
    rateNum.textContent = String(Math.round(bpm));
    hud.dataset.kind = ok ? "ok" : "no";
    if (ok) {
      inZone++;
      setWord(beatOn ? "Good — hold that" : "Good — it’s all you now", "ok");
    } else if (bpm < RATE_MIN) setWord("Faster", "no");
    else setWord("Slower", "no");
    count.textContent = String(Math.min(GOAL, inZone));

    // Plot the dot and scroll older ones left.
    const dots = [...dotsG.children];
    if (dots.length >= 28) dots[0].remove();
    [...dotsG.children].forEach((d, i, arr) => d.setAttribute("cx", 60 + (i + (28 - arr.length - 1)) * 19.4));
    dotsG.append(s("circle", { class: "tempo-dot " + (ok ? "is-ok" : "is-no"), cx: 60 + 27 * 19.4, cy: yFor(bpm), r: 6.5 }));

    if (beatOn && inZone >= GOAL / 2) {
      beatOn = false;
      beatRing.setAttribute("opacity", 0);
      ctx.say("<b>The beat is gone.</b> Keep the same tempo from memory — this is what it’s like for real.", "info");
    }
    if (inZone >= GOAL) finish();
  }

  function finish() {
    finished = true;
    metro?.stop();
    svg.classList.remove("is-pushable");
    const avg = Math.round(all.reduce((a, b) => a + b, 0) / all.length);
    const steady = Math.round((inZone / all.length) * 100);
    state.results.cpr = { avg, steady };
    setWord("That’s CPR", "ok");
    ctx.done(
      `${GOAL} pushes on tempo, averaging <b>${avg} a minute</b>. For real: push <b>5–6 cm deep</b> — harder than feels polite — let the chest spring back up, and don’t stop. It’s exhausting; swap with someone every 2 minutes.`
    );
  }

  svg.addEventListener("pointerdown", (e) => {
    if (!active || finished) return;
    e.preventDefault();
    wake();
    compress();
  });
  sc.on(window, "keydown", (e) => {
    if (e.code !== "Space" || !active || finished) return;
    e.preventDefault();
    if (!e.repeat) compress();
  });

  sc.frame((dt, now) => {
    if (!active) return;
    pressT = Math.max(0, pressT - dt * 6.5);
    const k = ease.out(pressT);
    hands.setAttribute("transform", `scale(${1 - 0.16 * k})`);
    torsoG.setAttribute("transform", `translate(300 ${150 + 3 * k}) scale(${3 + 0.03 * k} ${3 - 0.05 * k})`);
    ripple.setAttribute("r", 40 + 60 * (1 - pressT));
    ripple.setAttribute("opacity", pressT * 0.5);
    if (!finished && pushes > 1 && now - last > 1900) {
      setWord("Don’t stop", "no");
      hud.dataset.kind = "no";
    }
  });
}

// ── Step 4: shock ───────────────────────────────────────────────────────────────────────

function shock(ctx) {
  const { sc, stage } = ctx;
  const voice = h("div", { class: "aed-voice" }, h("span", { class: "aed-led" }), h("span", { class: "aed-text" }, "AED ON. “Attach pads to the patient’s bare chest.”"));
  stage.append(voice);
  const say = (t) => (voice.querySelector(".aed-text").textContent = t);

  const svg = ctx.svg("A bare chest seen from above, with places a pad could go");
  svg.append(s("ellipse", { class: "floor", cx: 300, cy: 300, rx: 250, ry: 215 }));
  const { g: torsoG } = torsoCloseUp(svg);
  svg.append(
    s("text", { class: "side-note", x: 150, y: 150, "text-anchor": "middle" }, "THEIR RIGHT"),
    s("text", { class: "side-note", x: 450, y: 150, "text-anchor": "middle" }, "THEIR LEFT")
  );

  const zones = [
    { x: 256, y: 206, ok: true, label: "Upper chest on their right, below the collarbone" },
    { x: 344, y: 206, label: "Upper chest on their left", why: "Both pads up high leaves the heart outside the path. One goes <b>upper right</b>, one <b>lower left</b> — so the current crosses the heart." },
    { x: 250, y: 312, label: "Lower ribs on their right", why: "Wrong side for the lower pad. It goes on their <b>left</b> side, under the armpit." },
    { x: 354, y: 312, ok: true, label: "Side of the chest on their left, below the armpit" },
    { x: 300, y: 372, label: "Stomach", why: "Not the stomach. The two pads need the heart between them." },
  ];
  let placed = 0;
  const zoneEls = zones.map((z) => {
    const g = s(
      "g",
      { class: "pad-zone", transform: `translate(${z.x} ${z.y})` },
      s("rect", { class: "pad-outline", x: -34, y: -27, width: 68, height: 54, rx: 9 }),
      s("rect", { class: "ring-hit", x: -40, y: -33, width: 80, height: 66, rx: 9 })
    );
    g.setAttribute("role", "button");
    g.setAttribute("tabindex", "0");
    g.setAttribute("aria-label", z.label);
    const act = () => {
      if (g.classList.contains("is-placed") || placed >= 2) return;
      if (!z.ok) {
        shake(g);
        ctx.say(z.why, "no");
        return;
      }
      sfx.tap();
      g.classList.add("is-placed");
      g.append(s("path", { class: "pad-bolt", d: "M4 -17 L-9 3 H0 L-4 17 L9 -3 H0 Z" }));
      placed++;
      if (placed === 1) ctx.say("One on. And the other?", "ok");
      if (placed === 2) analyse();
    };
    g.addEventListener("click", act);
    g.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        act();
      }
    });
    svg.append(g);
    return g;
  });

  ctx.say("Two pads. Tap the two places they go.", "info");

  async function analyse() {
    zoneEls.forEach((g) => !g.classList.contains("is-placed") && g.remove());
    ctx.say("Pads on. The pictures printed on real pads show exactly this.", "ok");
    say("“Analysing heart rhythm. Do not touch the patient.”");
    voice.classList.add("is-busy");
    await sc.wait(2200);
    voice.classList.remove("is-busy");
    say("“Shock advised. Stand clear. Press the flashing button.”");
    ctx.prompt("Everyone clear. Press it.", "Nobody touching the person — look, and say “stand clear” out loud. Then press the flashing button.");
    const btn = h("button", { class: "shock-btn", type: "button", "aria-label": "Deliver shock" }, s("svg", { viewBox: "-20 -24 40 48", "aria-hidden": "true" }, s("path", { d: "M5 -22 L-13 4 H-1 L-6 22 L13 -5 H1 Z" })));
    stage.append(btn);
    btn.focus({ preventScroll: true });
    btn.onclick = async () => {
      btn.remove();
      sfx.shock();
      stage.classList.add("flash");
      sc.tween(420, (t) => torsoG.setAttribute("transform", `translate(300 ${150 - Math.sin(t * Math.PI) * 14}) scale(3)`), ease.linear);
      await sc.wait(500);
      stage.classList.remove("flash");
      say("“Shock delivered. Continue CPR.”");
      ctx.done(
        "Straight back to pushing. <b>An AED only shocks a heart that needs it</b> — you cannot hurt someone with one, and it needs no training. It will re-check every 2 minutes."
      );
    };
  }
}

export default {
  id: "cpr",
  num: "01",
  name: "Collapse",
  blurb: "Their heart has stopped. Yours is racing. Check, call, push, shock.",
  minutes: 3,
  steps: [
    {
      tag: "Check",
      title: "Tap. Shout.",
      text: "Someone has just dropped to the floor in front of you. Tap both shoulders firmly and shout at them.",
      setup: check,
    },
    {
      tag: "Call",
      title: "Point at one person.",
      text: "A crowd has gathered. Each of them assumes someone else has already phoned. <b>Nobody has.</b> Choose one person: “You — call {n}. Put it on speaker.”",
      setup: call,
    },
    {
      tag: "Push",
      title: "Hands on the chest.",
      text: "Until a defibrillator arrives, <b>you are their heartbeat</b>. Your pushes are the only thing moving blood to the brain.",
      stageClass: "stage--push",
      setup: push,
    },
    {
      tag: "Shock",
      title: "The AED arrives.",
      text: "Open the lid or press the green button. <b>It talks.</b> It tells you every step. Keep pushing while someone else sticks the pads on.",
      stageClass: "stage--aed",
      setup: shock,
    },
  ],
  keepTitle: "Check. Call. Push. Shock.",
  keep: [
    { word: "Check", line: "No response and no normal breathing. Gasping doesn’t count." },
    { word: "Call", line: "{n}, on speaker. Point at one person to fetch an AED." },
    { word: "Push", line: "Centre of the chest. 100–120 a minute, 5–6 cm deep. Don’t stop." },
    { word: "Shock", line: "Switch the AED on and do exactly what it says." },
  ],
  also: [
    "<b>Child or baby, or someone pulled from water?</b> Air matters more. If you can, give 2 breaths after every 30 pushes. One hand for a child, two fingers for a baby, pressing a third of the chest’s depth.",
    "Without CPR, the chance of surviving falls about 10% each minute. With it, the odds double or triple.",
  ],
};

