// Drill 02 — choking. Silence is the emergency: five back blows, five thrusts.
import { s, ring, shake, ease } from "../ui.js";
import { Figure, FRONT_SPEC, SIDE_SPEC, pose } from "../figure.js";
import { sfx } from "../audio.js";

// ── Step 1: who needs you? ──────────────────────────────────────────────────────────────

function who(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("Two people at a table. One is coughing loudly, one is silent with hands at the throat.");
  svg.append(s("ellipse", { class: "floor", cx: 300, cy: 452, rx: 270, ry: 34 }));

  const make = (x, p, label, onPick) => {
    const fig = new Figure(FRONT_SPEC, p);
    const inner = s("g", {}, fig.el);
    const g = s(
      "g",
      { class: "bystander", transform: `translate(${x} 150) scale(1.7)` },
      s("rect", { class: "hit", x: -52, y: -60, width: 104, height: 246, rx: 10 }),
      inner
    );
    g.setAttribute("role", "button");
    g.setAttribute("tabindex", "0");
    g.setAttribute("aria-label", label);
    g.addEventListener("click", onPick);
    g.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        onPick();
      }
    });
    svg.append(g);
    return { g, inner, fig };
  };

  let solved = false;
  const a = make(165, pose({ elL: [-36, 24], haL: [-8, -10], head: [-3, -27] }), "Person A: coughing loudly, red in the face", () => {
    if (solved) return;
    shake(a.g);
    ctx.say("Not yet. A loud cough means air is moving, and a cough is stronger than anything you can do. Stay close and say <b>“keep coughing”</b>. Don’t slap their back.", "no");
  });
  const b = make(435, pose({ elL: [-34, 30], haL: [-7, -4], elR: [34, 30], haR: [7, -4] }), "Person B: silent, hands at the throat, cannot speak", () => {
    if (solved) return;
    solved = true;
    b.g.classList.add("is-chosen");
    ctx.done("<b>Silence is the emergency.</b> If they can’t cough, speak or breathe, the airway is fully blocked and they have a few minutes. Ask “Are you choking?” — a nod is enough. Act.");
  });

  // A coughs: jolts and noise words.
  const words = [
    s("text", { class: "noise", x: 62, y: 96, transform: "rotate(-12 62 96)" }, "KHAH!"),
    s("text", { class: "noise", x: 218, y: 78, transform: "rotate(9 218 78)" }, "KHH!"),
    s("text", { class: "noise", x: 232, y: 150, transform: "rotate(-5 232 150)" }, "HACK!"),
  ];
  words.forEach((w) => ((w.style.opacity = 0), svg.append(w)));
  let n = 0;
  const cough = () => {
    const w = words[n++ % words.length];
    sc.tween(
      520,
      (t) => {
        const k = Math.sin(Math.min(1, t * 1.6) * Math.PI);
        a.inner.setAttribute("transform", `translate(${-3 * k} ${5 * k}) rotate(${-5 * k})`);
        w.style.opacity = t < 0.75 ? 1 : (1 - t) * 4;
      },
      ease.linear
    );
  };
  sc.timeout(cough, 300);
  sc.interval(cough, 900);

  // B is silent: a faint tremor only.
  svg.append(s("text", { class: "silence", x: 435, y: 62, "text-anchor": "middle" }, "(no sound)"));
  sc.frame((dt, now) => {
    b.inner.setAttribute("transform", `translate(${Math.sin(now / 45) * 0.7} 0)`);
  });

  svg.append(s("text", { class: "letter", x: 165, y: 492, "text-anchor": "middle" }, "A"), s("text", { class: "letter", x: 435, y: 492, "text-anchor": "middle" }, "B"));
  ctx.say("Tap the person who needs you to step in.", "info");
}

// ── Side-view poses ─────────────────────────────────────────────────────────────────────

const VICTIM_BENT = {
  head: [170, 196],
  neck: [205, 214],
  hip: [322, 292],
  sh: [214, 226],
  elA: [212, 284],
  haA: [186, 250],
  elB: [222, 280],
  haB: [198, 246],
  knA: [318, 374],
  ftA: [316, 452],
  knB: [336, 372],
  ftB: [344, 452],
};

const RESCUER_BLOW = {
  head: [392, 124],
  neck: [404, 160],
  hip: [434, 292],
  sh: [404, 178],
  elB: [342, 240],
  haB: [262, 268], // supporting arm across their chest
  elA: [372, 126],
  haA: [330, 92], // striking arm, raised
  knA: [430, 374],
  ftA: [436, 452],
  knB: [452, 372],
  ftB: [470, 452],
};

const STRIKE = { elA: [346, 190], haA: [272, 198] };

function backBlows(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("Side view: you stand behind a choking person who is bent forward");
  svg.append(s("line", { class: "ground", x1: 40, y1: 466, x2: 560, y2: 466 }));
  const you = new Figure(SIDE_SPEC, RESCUER_BLOW, "is-you");
  const them = new Figure(SIDE_SPEC, VICTIM_BENT);
  const themWrap = s("g", {}, them.el);
  // Draw the far (supporting) arm of the rescuer behind the victim.
  svg.append(you.el, themWrap);
  // Bring the striking arm above the victim.
  const strikeArm = you.nodes[you.nodes.length - 1];
  const top = s("g", { class: "fig is-you" }, strikeArm.halo, strikeArm.p);
  svg.append(top);

  const counter = s("text", { class: "big-count", x: 520, y: 110, "text-anchor": "end" }, "0/5");
  const label = s("text", { class: "you-label", x: 462, y: 84, "text-anchor": "middle" }, "YOU");
  svg.append(counter, label);

  let n = 0;
  let busy = false;
  const target = ring(262, 204, 24, "Strike between the shoulder blades", async () => {
    if (busy || n >= 5) return;
    busy = true;
    await you.to(STRIKE, 90, sc, ease.linear);
    sfx.hit();
    n++;
    counter.textContent = n + "/5";
    counter.classList.remove("pop");
    void counter.getBBox();
    counter.classList.add("pop");
    sc.tween(240, (t) => themWrap.setAttribute("transform", `translate(${-9 * Math.sin(t * Math.PI)} ${7 * Math.sin(t * Math.PI)})`), ease.linear);
    await you.to({ elA: RESCUER_BLOW.elA, haA: RESCUER_BLOW.haA }, 200, sc, ease.out);
    busy = false;
    if (n === 5) {
      target.remove();
      ctx.done("Five. Still stuck. Each blow is a separate attempt to knock it loose — hard, with the heel of your hand — not a pat. Now switch to thrusts.");
    }
  });
  svg.append(target);
  ctx.say("Tap the target five times. Make each one count.", "info");
}

// ── Step 3: abdominal thrusts ───────────────────────────────────────────────────────────

const VICTIM_UP = {
  head: [262, 124],
  neck: [272, 160],
  hip: [296, 296],
  sh: [272, 178],
  elA: [238, 214],
  haA: [256, 164],
  elB: [246, 218],
  haB: [262, 170],
  knA: [294, 376],
  ftA: [292, 452],
  knB: [306, 376],
  ftB: [314, 452],
};

const RESCUER_HUG = {
  head: [344, 112],
  neck: [352, 150],
  hip: [374, 296],
  sh: [350, 172],
  elA: [318, 252],
  haA: [246, 258],
  elB: [326, 256],
  haB: [252, 264],
  knA: [366, 376],
  ftA: [366, 452],
  knB: [392, 374],
  ftB: [408, 452],
};

function thrusts(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("Side view: you stand behind the choking person with your arms around them");
  svg.append(s("line", { class: "ground", x1: 40, y1: 466, x2: 560, y2: 466 }));
  const them = new Figure(SIDE_SPEC, VICTIM_UP);
  const you = new Figure(SIDE_SPEC, { ...RESCUER_HUG, elA: [330, 236], haA: [306, 268], elB: [336, 240], haB: [312, 272] }, "is-you");
  const themWrap = s("g", {}, them.el);
  svg.append(you.el, themWrap);
  const arm = you.nodes[you.nodes.length - 1];
  const top = s("g", { class: "fig is-you" }, arm.halo, arm.p);
  svg.append(top);
  const counter = s("text", { class: "big-count", x: 540, y: 110, "text-anchor": "end" }, "");
  svg.append(counter, s("text", { class: "you-label", x: 420, y: 72, "text-anchor": "middle" }, "YOU"));

  const spots = [
    { x: 240, y: 198, label: "On the breastbone", why: "Too high for an adult — that’s the breastbone. Go lower, into the soft part." },
    { x: 246, y: 258, label: "Just above the navel, below the ribs", ok: true },
    { x: 254, y: 312, label: "Below the navel", why: "Too low. You want the soft spot <b>between the navel and the ribs</b>, to drive air up from the lungs." },
  ];
  const rings = spots.map((sp) =>
    ring(sp.x, sp.y, 20, sp.label, () => {
      if (!sp.ok) {
        shake(svg);
        ctx.say(sp.why, "no");
        return;
      }
      rings.forEach((r) => r.remove());
      grip();
    })
  );
  svg.append(...rings);
  ctx.say("Where does your fist go? Tap the spot.", "info");

  async function grip() {
    await you.to({ elA: RESCUER_HUG.elA, haA: RESCUER_HUG.haA, elB: RESCUER_HUG.elB, haB: RESCUER_HUG.haB }, 320, sc);
    ctx.prompt("In and up. Five times.", "Fist just above the navel, other hand on top. Pull sharply <b>inwards and upwards</b>, as if trying to lift them off the ground.");
    ctx.say("That’s the spot. Now thrust: tap five times.", "ok");
    counter.textContent = "0/5";
    let n = 0;
    let busy = false;
    const target = ring(246, 258, 24, "Thrust inwards and upwards", async () => {
      if (busy || n >= 5) return;
      busy = true;
      sfx.hit();
      n++;
      counter.textContent = n + "/5";
      counter.classList.remove("pop");
      void counter.getBBox();
      counter.classList.add("pop");
      you.to({ haA: [264, 240], haB: [270, 246], elA: [326, 244], elB: [334, 248] }, 80, sc, ease.linear);
      await sc.tween(260, (t) => themWrap.setAttribute("transform", `translate(${6 * Math.sin(t * Math.PI)} ${-10 * Math.sin(t * Math.PI)})`), ease.linear);
      you.to({ haA: RESCUER_HUG.haA, haB: RESCUER_HUG.haB, elA: RESCUER_HUG.elA, elB: RESCUER_HUG.elB }, 160, sc);
      busy = false;
      if (n === 5) {
        target.remove();
        pop();
      }
    });
    svg.append(target);
  }

  function pop() {
    const bit = s("circle", { class: "morsel", r: 9, cx: 236, cy: 132 });
    svg.append(bit);
    sfx.good();
    sc.tween(
      900,
      (t) => {
        bit.setAttribute("cx", 236 - 150 * t);
        bit.setAttribute("cy", 132 - 70 * Math.sin(t * Math.PI) + 300 * t * t);
      },
      ease.linear
    );
    them.to({ elA: [262, 238], haA: [240, 290], elB: [270, 240], haB: [250, 292] }, 500, sc);
    ctx.done(
      "It’s out. In real life, <b>keep alternating 5 blows and 5 thrusts</b> until it clears. Have someone call {n}. If they go limp: lower them to the floor and start CPR. Anyone who’s had thrusts should see a doctor afterwards."
    );
  }
}

export default {
  id: "choking",
  num: "02",
  name: "Choking",
  blurb: "Silence is the emergency. Five blows, five thrusts.",
  minutes: 1,
  steps: [
    {
      tag: "Spot it",
      title: "Who needs you?",
      text: "Dinner. Two people have something caught in their throat at the same moment. <b>One of them is in real danger.</b>",
      setup: who,
    },
    {
      tag: "5 blows",
      title: "Five back blows.",
      text: "Stand to the side and slightly behind. Support their chest with one hand and <b>lean them well forward</b>, so whatever comes loose falls out instead of further in. Hit hard between the shoulder blades with the heel of your hand.",
      setup: backBlows,
    },
    {
      tag: "5 thrusts",
      title: "Five abdominal thrusts.",
      text: "Stand behind them and wrap your arms around their waist. First: where does your fist go?",
      setup: thrusts,
    },
  ],
  keepTitle: "Five and five.",
  keep: [
    { word: "Coughing", line: "Leave them be. Say “keep coughing.” Stay close." },
    { word: "Silent", line: "Lean them forward. 5 hard blows between the shoulder blades." },
    { word: "Still stuck", line: "5 thrusts: fist above the navel, pull in and up. Repeat 5 and 5." },
    { word: "Goes limp", line: "Onto the floor. Call {n}. Start CPR." },
  ],
  also: [
    "<b>Baby under one:</b> face-down along your forearm, head lower than chest, 5 back blows. Turn over, 5 chest thrusts with two fingers. Never abdominal thrusts.",
    "<b>Pregnant, or too large to reach around:</b> thrust on the breastbone instead. <b>Alone and choking:</b> drive your upper belly onto the back of a chair.",
  ],
};

// Drill 03 — severe bleeding. Press, don't peek, pack on top, tourniquet above.
import { h, s, ring, shake, clamp, ease } from "../ui.js";
import { choiceStep } from "../drill.js";
import { sfx, wake } from "../audio.js";

const HOLD_SECONDS = 8;

function arm(svg, { woundX }) {
  // A forearm lying across the stage: body to the left, hand to the right.
  svg.append(
    s("path", { class: "limb", d: "M-40 236 H452" }),
    s("path", { class: "limb-hand", d: "M452 236 H516" }),
    s("path", { class: "limb-thumb", d: "M468 214 L500 172" }),
    s("path", { class: "wound", d: `M${woundX - 24} 250 l12 -22 l8 14 l10 -24 l8 16 l10 -18` })
  );
}

// ── Step 1: press and hold ──────────────────────────────────────────────────────────────

function press(ctx) {
  const { sc, stage } = ctx;
  const lostNum = h("b", {}, "0.0");
  const word = h("div", { class: "hud-word" }, "Bleeding");
  const clockNum = h("b", {}, "0:00");
  const hud = h(
    "div",
    { class: "hud" },
    h("div", { class: "hud-rate" }, lostNum, h("span", {}, "litres lost · about 5 in a body")),
    word,
    h("div", { class: "hud-count" }, clockNum, h("span", {}, "of 10:00 held"))
  );
  stage.append(hud);

  const svg = ctx.svg("A forearm with a deep wound, bleeding onto the floor");
  const pool = s("ellipse", { class: "blood", cx: 300, cy: 438, rx: 10, ry: 4 });
  const stream = s("path", { class: "blood-stream", d: "M300 262 V436" });
  svg.append(pool, stream);
  arm(svg, { woundX: 300 });

  const cloth = s("rect", { class: "cloth", x: 244, y: 180, width: 112, height: 112, rx: 10, transform: "rotate(-6 300 236)" });
  const soak = s("circle", { class: "soak", cx: 300, cy: 240, r: 0 });
  const palm = s(
    "g",
    { class: "palm" },
    s("rect", { class: "hand", x: 258, y: 196, width: 84, height: 62, rx: 22 }),
    s("path", { class: "hand-fingers", d: "M270 196 V160 M290 196 V150 M310 196 V152 M330 196 V164 M258 232 L232 214" })
  );
  const C = 2 * Math.PI * 78;
  const prog = s("circle", { class: "hold-ring", cx: 300, cy: 236, r: 78, "stroke-dasharray": C, "stroke-dashoffset": C, transform: "rotate(-90 300 236)" });
  const dressing = s("g", { opacity: 0 }, cloth, soak, palm, prog);
  svg.append(dressing);

  const target = ring(300, 236, 34, "Press and hold on the wound", () => {});
  target.classList.add("ring--hold");
  svg.append(target);
  const cue = s("text", { class: "cue", x: 300, y: 122, "text-anchor": "middle" }, "PRESS AND HOLD — DON’T LET GO");
  svg.append(cue);

  let holding = false;
  let held = 0;
  let lost = 0.2;
  let finished = false;
  let peeks = 0;

  const start = (e) => {
    if (finished || holding) return;
    e?.preventDefault?.();
    wake();
    holding = true;
    sfx.hit();
    dressing.setAttribute("opacity", 1);
    target.classList.add("is-held");
    word.textContent = "Pressing";
    hud.dataset.kind = "ok";
    cue.textContent = "KEEP PRESSING";
  };
  const stop = () => {
    if (!holding || finished) return;
    holding = false;
    peeks++;
    held = 0;
    dressing.setAttribute("opacity", 0);
    target.classList.remove("is-held");
    word.textContent = "Bleeding again";
    hud.dataset.kind = "no";
    cue.textContent = "PRESS AND HOLD — DON’T LET GO";
    shake(svg);
    ctx.say("<b>You let go.</b> Lifting off to look tears away the clot that was forming, and the clock starts again. Press and keep pressing.", "no");
  };

  target.addEventListener("pointerdown", (e) => {
    target.setPointerCapture?.(e.pointerId);
    start(e);
  });
  target.addEventListener("pointerup", stop);
  target.addEventListener("pointercancel", stop);
  target.addEventListener("contextmenu", (e) => e.preventDefault());
  target.addEventListener("keydown", (e) => {
    if ((e.key === " " || e.key === "Enter") && !e.repeat) start(e);
  });
  target.addEventListener("keyup", (e) => {
    if (e.key === " " || e.key === "Enter") stop();
  });
  target.addEventListener("blur", stop);

  ctx.say("Press on the wound and hold. Mouse, finger, or Space bar.", "info");

  sc.frame((dt, now) => {
    if (finished) return;
    if (holding) {
      held += dt;
      const p = clamp(held / HOLD_SECONDS, 0, 1);
      prog.setAttribute("stroke-dashoffset", C * (1 - p));
      soak.setAttribute("r", 8 + 30 * p);
      clockNum.textContent = Math.floor(p * 10) + ":" + String(Math.floor((p * 600) % 60)).padStart(2, "0");
      stream.style.opacity = 0;
      if (p >= 1) {
        finished = true;
        clockNum.textContent = "10:00";
        word.textContent = "Held";
        cue.textContent = "";
        target.classList.add("is-complete");
        state_done();
      }
    } else {
      lost = Math.min(2.6, lost + dt * 0.055);
      stream.style.opacity = 1;
      stream.setAttribute("stroke-dashoffset", -now / 9);
      clockNum.textContent = "0:00";
    }
    lostNum.textContent = lost.toFixed(1);
    const k = lost / 2.6;
    pool.setAttribute("rx", 16 + 230 * Math.sqrt(k));
    pool.setAttribute("ry", 5 + 34 * Math.sqrt(k));
    if (lost > 1.5 && !holding) {
      word.textContent = "Critical";
    }
  });

  function state_done() {
    ctx.done(
      (peeks ? "That’s it — no peeking this time. " : "Rock steady. ") +
        "Firm, direct pressure stops most bleeding, even bad bleeding. Use any cloth, or your bare hands. Lean your body weight into it and <b>hold for a full 10 minutes</b>, or until help takes over."
    );
  }
}

// ── Step 3: tourniquet ──────────────────────────────────────────────────────────────────

function tourniquet(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("An arm from shoulder to hand, with a wound on the forearm");
  svg.append(s("ellipse", { class: "blood", cx: 390, cy: 420, rx: 150, ry: 26 }));
  svg.append(s("path", { class: "blood-stream", d: "M390 262 V418" }));
  arm(svg, { woundX: 390 });
  svg.append(
    s("path", { class: "crease", d: "M222 196 q10 40 0 80" }),
    s("text", { class: "side-note", x: 60, y: 160 }, "← TO THE HEART"),
    s("text", { class: "side-note", x: 222, y: 330, "text-anchor": "middle" }, "ELBOW"),
    s("text", { class: "side-note", x: 390, y: 330, "text-anchor": "middle" }, "WOUND")
  );

  const spots = [
    { x: 222, label: "On the elbow", why: "Never on a joint — the strap can’t squeeze an artery against a hinge. Go above or below the joint." },
    { x: 312, ok: true, label: "A hand’s width above the wound, between wound and heart" },
    { x: 390, label: "Directly on the wound", why: "Not on the wound itself. A tourniquet goes <b>above</b> it, to shut off the supply." },
    { x: 448, label: "Below the wound, towards the hand", why: "Blood arrives from the heart side. Tighten there and the wound keeps pouring. Go <b>between the wound and the heart</b>." },
  ];
  const rings = spots.map((sp) =>
    ring(sp.x, 236, 22, sp.label, () => {
      if (!sp.ok) {
        shake(svg);
        ctx.say(sp.why, "no");
        return;
      }
      rings.forEach((r) => r.remove());
      apply(sp.x);
    })
  );
  svg.append(...rings);
  ctx.say("Tap where the tourniquet goes.", "info");

  async function apply(x) {
    sfx.tap();
    const strap = s("path", { class: "strap", d: `M${x} 180 V292` });
    const rod = s("path", { class: "rod", d: `M${x - 34} 236 H${x + 34}`, transform: `rotate(0 ${x} 236)` });
    svg.append(strap, rod);
    const stream = svg.querySelector(".blood-stream");
    await sc.tween(
      1300,
      (t) => {
        rod.setAttribute("transform", `rotate(${t * 540 + 20} ${x} 236)`);
        strap.setAttribute("stroke-width", 22 - 6 * t);
        stream.style.opacity = 1 - t;
      },
      ease.inOut
    );
    const now = new Date();
    const stamp = String(now.getHours()).padStart(2, "0") + ":" + String(now.getMinutes()).padStart(2, "0");
    svg.append(s("text", { class: "stamp", x: x, y: 150, "text-anchor": "middle" }, "T " + stamp));
    ctx.done(
      "5–7 cm above the wound, never on a joint. <b>Twist until the bleeding stops</b> — it will hurt, and that is correct. Write the time on it or on their skin. Do not loosen it; that’s for the hospital. If unsure where: go high on the limb, and tight."
    );
  }
}

export default {
  id: "bleeding",
  num: "03",
  name: "Bleeding",
  blurb: "A person can bleed to death in five minutes. Your hands are the bandage.",
  minutes: 1,
  steps: [
    {
      tag: "Press",
      title: "Press hard. Stay there.",
      text: `Blood is pouring from a deep cut. Someone is calling {n}. A person can bleed to death in <b>five minutes</b> — long before an ambulance. Press on the wound and hold for ${HOLD_SECONDS} seconds; here, that stands for ten minutes.`,
      stageClass: "stage--push",
      setup: press,
    },
    choiceStep({
      tag: "Soaked",
      title: "The cloth is soaked through.",
      text: "Blood is coming through the shirt you’re pressing with.",
      scene: "Three minutes in",
      quote: "The cloth under your hands is red and wet. Blood is starting to seep between your fingers.",
      options: [
        { label: "Take it off and put on a fresh one", why: "That pulls the forming clot away with it — you’re back to zero. Leave it where it is." },
        { label: "Put another on top and press harder", ok: true, why: "Yes. <b>Never remove, only add.</b> More cloth on top, more weight behind it. If the wound is deep and wide, pack cloth into it and press on that." },
        { label: "Lift a corner to check on it", why: "Don’t peek. If it’s soaking through, you already know the answer: more pressure." },
      ],
    }),
    {
      tag: "Tourniquet",
      title: "It won’t stop.",
      text: "It’s an arm, and pressure isn’t enough. Time for a tourniquet: a proper one if there is one, otherwise a wide strip of cloth twisted tight with a stick. <b>Where does it go?</b>",
      setup: tourniquet,
    },
  ],
  keepTitle: "Press. Don’t peek.",
  keep: [
    { word: "Press", line: "Hard, straight onto the wound. Cloth or bare hands. Ten minutes." },
    { word: "Don’t peek", line: "Soaked through? Add more on top. Never lift it off." },
    { word: "Tourniquet", line: "Arm or leg that won’t stop: 5–7 cm above the wound, not on a joint, twisted tight." },
    { word: "Time", line: "Note when it went on. Call {n}. Keep them lying down and warm." },
  ],
  also: [
    "<b>Something stuck in the wound?</b> Leave it in — it may be plugging the hole. Press around it, not on it.",
  ],
};

// Drill 04 — stroke. Face, Arms, Speech, Time.
import { h, s, lerp, ease } from "../ui.js";
import { choiceStep } from "../drill.js";
import { sfx } from "../audio.js";

function fastTest(ctx) {
  const { sc, stage } = ctx;
  const svg = ctx.svg("A person facing you, head and shoulders");

  // Bust
  const armL = s("path", { class: "fig-limb", "stroke-width": 40 });
  const armR = s("path", { class: "fig-limb", "stroke-width": 40 });
  const body = s("path", { class: "fig-body", "stroke-width": 44, d: "M214 338 H386 L372 540 H228 Z" });
  const neck = s("path", { class: "fig-limb", "stroke-width": 52, d: "M300 262 V316" });
  const head = s("circle", { class: "fig-head", cx: 300, cy: 178, r: 96 });
  const eyeL = s("ellipse", { class: "face", cx: 264, cy: 160, rx: 9, ry: 11 });
  const eyeR = s("ellipse", { class: "face", cx: 336, cy: 160, rx: 9, ry: 11 });
  const browL = s("path", { class: "face-line", d: "M248 136 L280 132" });
  const browR = s("path", { class: "face-line" });
  const mouth = s("path", { class: "face-line face-mouth" });
  svg.append(s("g", { class: "fig" }, armL, armR, body, neck, head), eyeL, eyeR, browL, browR, mouth);

  const bubble = s(
    "g",
    { class: "bubble", opacity: 0 },
    s("path", { d: "M398 40 h170 a14 14 0 0 1 14 14 v62 a14 14 0 0 1 -14 14 h-120 l-34 26 l8 -26 h-24 a14 14 0 0 1 -14 -14 v-62 a14 14 0 0 1 14 -14 z" }),
    s("text", { x: 404, y: 80 }, ""),
    s("text", { x: 404, y: 110 }, "")
  );
  svg.append(bubble);

  const face = { smile: 0, droop: 0 };
  const arms = { l: 0, r: 0, drift: 0 };
  function draw() {
    const sm = face.smile;
    const d = face.droop * (0.3 + 0.7 * sm);
    const Lx = 256 - 6 * sm;
    const Ly = 226 - 14 * sm;
    const Rx = 344 + 6 * sm * (1 - d) - 4 * d;
    const Ry = 226 - 14 * sm * (1 - d) + 20 * d;
    const Cx = 300 - 10 * d;
    const Cy = 232 + 30 * sm - 6 * d;
    mouth.setAttribute("d", `M${Lx} ${Ly} Q${Cx} ${Cy} ${Rx} ${Ry}`);
    eyeR.setAttribute("ry", 11 - 6 * d);
    eyeR.setAttribute("cy", 160 + 5 * d);
    browR.setAttribute("d", `M320 132 L352 ${136 + 12 * d}`);
    // Arms: 0 = hanging, 1 = held out.
    const a = (side, up, drift) => {
      const sx = 300 + side * 88;
      const downE = [300 + side * 120, 440];
      const downH = [300 + side * 124, 560];
      const upE = [300 + side * 166, 300];
      const upH = [300 + side * 246, 252];
      const driftE = [300 + side * 158, 388];
      const driftH = [300 + side * 214, 470];
      let E = [lerp(downE[0], upE[0], up), lerp(downE[1], upE[1], up)];
      let H = [lerp(downH[0], upH[0], up), lerp(downH[1], upH[1], up)];
      E = [lerp(E[0], driftE[0], drift), lerp(E[1], driftE[1], drift)];
      H = [lerp(H[0], driftH[0], drift), lerp(H[1], driftH[1], drift)];
      return `M${sx} 340 L${E[0]} ${E[1]} L${H[0]} ${H[1]}`;
    };
    armL.setAttribute("d", a(-1, arms.l, 0));
    armR.setAttribute("d", a(1, arms.r, arms.drift));
  }
  draw();

  // The four letters, lighting up as each test is run.
  const cells = [
    ["F", "Face", "One side droops"],
    ["A", "Arms", "One drifts down"],
    ["S", "Speech", "Slurred or strange"],
    ["T", "Time", "Call {n} now"],
  ].map(([letter, wordText, finding]) => {
    const el = h(
      "div",
      { class: "fast-cell" },
      h("span", { class: "fast-letter" }, letter),
      h("span", { class: "fast-word" }, wordText),
      h("span", { class: "fast-find" }, finding.replace("{n}", ctx.sc ? "" : ""))
    );
    return el;
  });
  cells[3].querySelector(".fast-find").textContent = "Call now";
  stage.append(h("div", { class: "fast" }, cells));

  let doneCount = 0;
  const light = (i) => {
    cells[i].classList.add("is-on");
    sfx.tap();
    doneCount++;
    if (doneCount === 3) {
      sc.timeout(() => {
        cells[3].classList.add("is-on", "is-time");
        ctx.done(
          "<b>Any one of those signs is enough.</b> Call {n}, say “stroke”, and note the time the symptoms started — the treatments that reverse a stroke only work in the first few hours. Every minute untreated costs about two million brain cells."
        );
      }, 900);
    }
  };

  const tests = [
    {
      label: "“Can you smile for me?”",
      run: async (b) => {
        face.droop = 1;
        await sc.tween(900, (t) => ((face.smile = t), draw()), ease.inOut);
        ctx.say("One side of the mouth doesn’t lift, and that eyelid sags. That’s <b>F — Face</b>.", "info");
        light(0);
      },
    },
    {
      label: "“Raise both arms and hold them.”",
      run: async () => {
        await sc.tween(700, (t) => ((arms.l = t), (arms.r = t), draw()), ease.inOut);
        await sc.wait(500);
        await sc.tween(1500, (t) => ((arms.drift = t), draw()), ease.inOut);
        ctx.say("One arm sinks and they can’t stop it. That’s <b>A — Arms</b>.", "info");
        light(1);
      },
    },
    {
      label: "“Say: the sky is blue today.”",
      run: async () => {
        bubble.setAttribute("opacity", 1);
        const lines = ["Th’ ssky… izz", "boo… t’ddday…"];
        const [t1, t2] = bubble.querySelectorAll("text");
        for (const [node, line] of [
          [t1, lines[0]],
          [t2, lines[1]],
        ]) {
          for (let i = 1; i <= line.length; i++) {
            node.textContent = line.slice(0, i);
            await sc.wait(65);
          }
        }
        ctx.say("Slurred, jumbled, or they can’t find the words. That’s <b>S — Speech</b>.", "info");
        light(2);
      },
    },
  ];

  let busy = false;
  const buttons = tests.map((t) => {
    const b = h("button", { class: "btn btn-choice", type: "button" }, t.label);
    b.onclick = async () => {
      if (busy) return;
      busy = true;
      b.disabled = true;
      b.classList.add("is-right");
      await t.run(b);
      busy = false;
    };
    return b;
  });
  ctx.actions.append(...buttons);
  ctx.say("Ask all three. Watch closely.", "info");
}

export default {
  id: "stroke",
  num: "04",
  name: "Stroke",
  blurb: "Three questions that take ten seconds, and a clock you can’t see.",
  minutes: 1,
  steps: [
    {
      tag: "Test",
      title: "Something’s off.",
      text: "Your friend stops mid-sentence and looks confused. They say they’re fine. <b>Ask them three things.</b>",
      stageClass: "stage--fast",
      setup: fastTest,
    },
    choiceStep({
      tag: "Decide",
      title: "And then it passes.",
      text: "Do you still make the call?",
      scene: "Ten minutes later",
      quote: "“Look — my arm’s fine again. I can talk. Honestly, it’s nothing. Don’t make a fuss. I’ll just lie down for a bit.”",
      options: [
        { label: "Let them rest and check on them in an hour", why: "This is how people lose the treatment window. A stroke that “passes” is often a warning: the big one tends to follow within hours or days." },
        { label: "Call {n} anyway", ok: true, why: "Yes. Symptoms that vanish are a <b>mini-stroke (TIA)</b> — an emergency in its own right. Call, and tell them exactly when it started." },
        { label: "Give them an aspirin and some water", why: "No food, no drink, no pills. Swallowing may not work properly, and aspirin makes a bleeding stroke worse. Just call." },
      ],
    }),
  ],
  keepTitle: "Face. Arms. Speech. Time.",
  keep: [
    { word: "Face", line: "Ask for a smile. Does one side droop?" },
    { word: "Arms", line: "Both arms up. Does one drift down?" },
    { word: "Speech", line: "A simple sentence. Slurred? Jumbled? Nothing?" },
    { word: "Time", line: "One sign is enough. Call {n}. Note when it started." },
  ],
  also: [
    "Also sudden: loss of vision, loss of balance, numbness on one side, or the worst headache of their life. <b>Sudden is the word.</b> Don’t give food, drink or medicine, and don’t let them talk you out of calling.",
  ],
};

// Drill 05 — out cold but breathing. The recovery position, and what not to do in a seizure.
import { s, ring, ease } from "../ui.js";
import { Figure, FRONT_SPEC, FRONT } from "../figure.js";
import { choiceStep } from "../drill.js";
import { sfx } from "../audio.js";

const SCALE = 2;
const OX = 168;
const OY = 236;
/** Figure coordinates → stage coordinates (the figure lies head-left, near side towards you). */
const at = ([x, y]) => [OX + y * SCALE, OY - x * SCALE];

const P1 = { elL: [-50, 8], haL: [-54, -26] };
const P2 = { elR: [6, 30], haR: [-13, -9] };
const P3 = { knR: [19, 108], ftR: [17, 132] };
const P4 = {
  head: [-5, -30],
  shL: [-15, 5],
  shR: [-3, 3],
  hipL: [-15, 78],
  hipR: [-5, 78],
  elL: [-50, 10],
  haL: [-54, -24],
  elR: [-30, 22],
  haR: [-15, -15],
  knR: [-50, 80],
  ftR: [-53, 124],
  knL: [-14, 126],
  ftL: [-12, 174],
};
const P5 = { head: [-1, -35] };

function roll(ctx) {
  const { sc } = ctx;
  const svg = ctx.svg("A person lying on their back, seen from above. You kneel at the bottom of the picture.");
  svg.append(s("ellipse", { class: "floor", cx: 300, cy: 250, rx: 282, ry: 150 }));
  const g = s("g", { transform: `translate(${OX} ${OY}) rotate(-90) scale(${SCALE})` });
  const fig = new Figure(FRONT_SPEC, FRONT);
  g.append(fig.el);
  svg.append(g);

  // You, kneeling beside them.
  svg.append(
    s(
      "g",
      { class: "you-top", transform: "translate(300 452)" },
      s("rect", { x: -44, y: -6, width: 88, height: 34, rx: 17 }),
      s("circle", { r: 21, cy: -4 })
    ),
    s("text", { class: "you-label", x: 368, y: 462 }, "YOU")
  );

  // Calm, regular breathing — the opposite of the gasps in drill 01.
  const breath = s(
    "g",
    { class: "gasp breath" },
    s("path", { d: "M70 214 q-14 -8 -26 -3" }),
    s("path", { d: "M64 240 h-28" }),
    s("path", { d: "M70 266 q-14 8 -26 3" })
  );
  svg.append(breath);
  const torso = fig.nodes[2].p;
  sc.frame((dt, now) => {
    const k = (Math.sin(now / 520) + 1) / 2;
    breath.setAttribute("opacity", 0.15 + 0.6 * k);
    torso.setAttribute("stroke-width", 14 + 2.2 * k);
  });

  const stepNo = s("text", { class: "big-count", x: 560, y: 70, "text-anchor": "end" }, "1/5");
  svg.append(stepNo);

  const moves = [
    {
      point: () => fig.pose.haL,
      label: "Move the near arm out",
      title: "Near arm: out of the way.",
      text: "Kneel beside them. Take the arm nearest you and lay it out at a right angle, elbow bent, palm up.",
      to: P1,
    },
    {
      point: () => fig.pose.haR,
      label: "Bring the far hand to the near cheek",
      title: "Far hand: to their cheek.",
      text: "Bring the far arm across the chest and hold the back of that hand against the cheek nearest you. It will cushion the head.",
      to: P2,
    },
    {
      point: () => fig.pose.knR,
      label: "Pull the far knee up",
      title: "Far knee: up.",
      text: "With your other hand, pull the far knee up until the foot is flat on the floor. That bent leg is your lever.",
      to: P3,
    },
    {
      point: () => fig.pose.knR,
      label: "Pull the knee to roll them towards you",
      title: "Pull the knee. Roll them to you.",
      text: "Keep their hand pressed to their cheek and pull on the raised knee. They roll onto their side — it takes far less strength than you’d think.",
      to: P4,
      ms: 900,
    },
    {
      point: () => fig.pose.head,
      label: "Tilt the head back",
      title: "Head back. Mouth down.",
      text: "Gently tilt the head back to open the airway, with the mouth angled toward the floor so anything in it drains out.",
      to: P5,
    },
  ];

  let i = 0;
  let current = null;
  function arm() {
    const m = moves[i];
    stepNo.textContent = `${i + 1}/5`;
    ctx.prompt(m.title, m.text);
    const [x, y] = at(m.point());
    current = ring(x, y, 22, m.label, async () => {
      current.remove();
      sfx.tap();
      await fig.to(m.to, m.ms || 550, sc, ease.inOut);
      i++;
      if (i < moves.length) arm();
      else finish();
    });
    svg.append(current);
    if (i > 0) current.focus({ preventScroll: true });
  }
  arm();
  ctx.say("Tap the glowing spot to make each move.", "info");

  function finish() {
    svg.append(s("path", { class: "airway", d: "M98 250 q-26 14 -52 6", "marker-end": "" }));
    ctx.done(
      "On their back, the tongue or vomit can silently block the airway. On their side, it can’t. Call {n}, <b>keep watching the breathing</b>, and if it stops, roll them back and start CPR."
    );
  }
}

export default {
  id: "recovery",
  num: "05",
  name: "Out cold",
  blurb: "Unresponsive, but breathing. Five moves that keep an airway open.",
  minutes: 2,
  steps: [
    {
      tag: "Roll",
